54	fn key_from_keycode(keycode: i64) -> Option<SystemKey> {
55	    match keycode as u16 {
56	        KeyCode::FUNCTION => Some(SystemKey::Fn),
57	        KeyCode::CONTROL => Some(SystemKey::LeftControl),
58	        KeyCode::RIGHT_CONTROL => Some(SystemKey::RightControl),
59	        KeyCode::OPTION => Some(SystemKey::LeftOption),
60	        KeyCode::RIGHT_OPTION => Some(SystemKey::RightOption),
61	        KeyCode::COMMAND => Some(SystemKey::LeftCommand),
62	        KeyCode::RIGHT_COMMAND => Some(SystemKey::RightCommand),
63	        _ => None,
64	    }
65	}
