67	fn key_is_down_in_flags(key: SystemKey, flags: CGEventFlags) -> bool {
68	    match key {
69	        SystemKey::Fn => flags.contains(CGEventFlags::CGEventFlagSecondaryFn),
70	        SystemKey::LeftControl | SystemKey::RightControl => {
71	            flags.contains(CGEventFlags::CGEventFlagControl)
72	        }
73	        SystemKey::LeftOption | SystemKey::RightOption => {
74	            flags.contains(CGEventFlags::CGEventFlagAlternate)
75	        }
76	        SystemKey::LeftCommand | SystemKey::RightCommand => {
77	            flags.contains(CGEventFlags::CGEventFlagCommand)
78	        }
79	    }
80	}
