82	fn emit_system_key_event(event: &CGEvent) {
83	    let Some(app_handle) = APP_HANDLE.get() else {
84	        return;
85	    };
86	
87	    let keycode = event.get_integer_value_field(EventField::KEYBOARD_EVENT_KEYCODE);
88	    let Some(key) = key_from_keycode(keycode) else {
89	        return;
90	    };
91	
92	    let flags = event.get_flags();
93	    let is_down = key_is_down_in_flags(key, flags);
94	    let mut pressed = pressed_keys()
95	        .lock()
96	        .expect("system key pressed state mutex poisoned");
97	
98	    if is_down {
99	        let was_new_key = pressed.insert(key);
100	
101	        if was_new_key {
102	            let _ = app_handle.emit(
103	                "system-key-pressed",
104	                SystemKeyPressedPayload {
105	                    key,
106	                    pressed_keys: pressed.iter().copied().collect(),
107	                },
108	            );
109	        }
110	
111	        return;
112	    }
113	
114	    if pressed.remove(&key) {
115	        let pressed_keys = pressed.iter().copied().collect::<Vec<_>>();
116	        let _ = app_handle.emit(
117	            "system-key-released",
118	            SystemKeyReleasedPayload { key, pressed_keys },
119	        );
120	
121	        if pressed.is_empty() {
122	            let _ = app_handle.emit("system-keys-released", ());
123	        }
124	    }
125	}
