124			void Result.tryPromise(() => emit("hotkey-recorder-active", { active }));
125		};
126	
127		const saveRecordedHotkey = async (hotkey: string) => {
128			const validationError = options.validator?.(hotkey);
129			if (validationError) {
130				setError(validationError);
131				return false;
132			}
133			setError(null);
134			const saved = await Result.tryPromise(async () => {
135				await (options.onHotkeyRecorded?.(hotkey) ?? updateHotkey(hotkey));
136			});
137			if (Result.isError(saved)) {
138				return false;
139			}
140			return true;
141		};
142	
143		/**
144		 * Build a display string for currently held modifiers.
145		 */
146		const buildModifierDisplay = (codes: Set<string>): string => {
147			if (codes.size === 1) {
148				const first = codes.values().next();
149				if (first.done) return "";
150				return modifierCodeToDisplay(first.value) ?? first.value;
151			}
152			const parts: string[] = [];
153			for (const mc of MOD_ORDER) {
154				if (codes.has(mc)) {
