202				if (systemHotkey && pendingSystemHotkey) {
203					heldModifierCodes.delete(code);
204					return;
205				}
206	
207				if (heldModifierCodes.size === 1 && heldModifierCodes.has(code) && systemHotkey) {
208					const success = await saveRecordedHotkey(systemHotkey);
209					if (success) {
