144	/**
145	 * Convert a KeyboardEvent.code modifier into the system-only hotkey string
146	 * persisted in settings, when the native watcher supports it.
147	 */
148	export function modifierCodeToSystemHotkey(code: string): string | undefined {
149		return MODIFIER_CODE_TO_SYSTEM_HOTKEY[code];
150	}
