187	/**
188	 * Check if a hotkey should be handled by the native system key watcher.
189	 */
190	export function isSystemOnlyHotkey(hotkey: string): boolean {
191		return systemKeysFromHotkey(hotkey) !== undefined;
192	}
193	
194	/**
195	 * Check if a hotkey string can be registered by one of the supported backends.
196	 */
197	export function isValidHotkey(hotkey: string): boolean {
198		if (isSystemOnlyHotkey(hotkey)) return true;
199	
200		const parts = hotkey
201			.split("+")
202			.map((part) => part.trim())
203			.filter(Boolean);
204		if (parts.length < 2) return false;
205		if (parts.some((part) => part in SYSTEM_HOTKEY_TO_KEY)) return false;
206	
207		const key = parts[parts.length - 1];
208		if (!key || COMBO_MODIFIER_NAMES.has(key)) return false;
209	
210		return parts.slice(0, -1).every((part) => COMBO_MODIFIER_NAMES.has(part));
211	}
