309	export async function registerDictationHotkeys(
310		hotkeys: { hotkey: string; onPressed: HotkeyHandler; onReleased?: HotkeyHandler }[]
311	): Promise<void> {
312		await unregisterDictationHotkey();
313	
314		const registered: RegisteredHotkey[] = [];
315		const result = await Result.tryPromise(async () => {
316			for (const config of hotkeys) {
317				registered.push(
318					isSystemOnlyHotkey(config.hotkey)
319						? await registerSystemHotkey(config.hotkey, config)
320						: await registerGlobalHotkey(config.hotkey, config)
321				);
322			}
323		});
324		if (Result.isError(result)) {
325			for (const registration of registered) {
326				await registration.dispose();
327			}
328			throw result.error;
329		}
330		registeredDictationHotkeys = registered;
331	}
